```javascript
function handleClick() {
  setCount(c => c + 1);
  setFlag(f => !f);
  setData(d => [...d, newItem]);
  // Only one re-render occurs, not three
}

setTimeout(() => {
  setCount(c => c + 1);
  setFlag(f => !f);
